#!/usr/bin/env bash
#
# deploy_wemix_homepage.sh — replaces frontend/index.html with the new
# WEMIX-styled editorial homepage (matching the reference screenshot:
# utility bar, dark navy nav, breaking news ticker, hero carousel,
# Editor's Picks, Trending Now, category icons, newsletter bar, footer).
#
# HONESTY NOTES on what's real vs. visual-only, worth reading:
#   - Hero/Editor's Picks: real "featured" listings (a real backend
#     field), falling back to most recent if none are marked featured.
#   - Latest News / Trending Now: real data (Trending reuses the
#     existing ?trending=1 endpoint, already built).
#   - Top Categories: your real Category API data, with a small set of
#     distinct icons matched by category name (politics/business/
#     technology/etc.), falling back to a generic icon.
#   - "Across Tanzania" (renamed from the reference's "Around the
#     World"): uses REAL listings that have a location set. I did not
#     hardcode fake international headlines (the reference image shows
#     fabricated New York/London/Tokyo stories) -- that would directly
#     contradict "AI-verified real news" being the platform's whole
#     point. If fewer than a handful of listings have a location set,
#     this section hides itself gracefully instead of showing fake data.
#   - The 28°C weather reading in the reference is dropped -- no real
#     weather API is wired up, so showing a fake temperature would be
#     actively misleading. Real date is still shown.
#   - Live TV / Podcast / Newsletter signup / "WEMIX LIVE Watch Live":
#     no backend exists for any of these yet. They're kept as visual
#     chrome matching the reference image, but genuinely inert --
#     Watch Live is disabled with a tooltip explaining why, and the
#     newsletter form shows an honest "not available yet" message
#     instead of pretending to subscribe someone.
#   - Search bar and category nav are fully real -- they query your
#     actual /api/news/listings/ endpoint and show real results.
#
# Tested with Playwright against realistic mocked API data (categories,
# featured/trending/location-tagged listings) before shipping: confirmed
# the hero rotates through real featured stories, categories render with
# matching icons, trending/latest/around-Tanzania sections populate
# correctly, and zero horizontal overflow at 320/375/768/1024/1440px.
#
# Run this from YOUR OWN machine:
#   chmod +x deploy_wemix_homepage.sh
#   ./deploy_wemix_homepage.sh

set -euo pipefail

SERVER_IP="196.250.208.206"
SERVER_USER="samson"
REMOTE_BASE_DIR="/home/${SERVER_USER}/habari_platform"

if ! command -v sshpass >/dev/null 2>&1; then
  echo "This needs sshpass. Install it: sudo apt-get install -y sshpass"
  exit 1
fi

if [ -z "${DEPLOY_PASSWORD:-}" ]; then
  read -r -s -p "SSH password for ${SERVER_USER}@${SERVER_IP}: " DEPLOY_PASSWORD
  echo
fi

SSH_OPTS="-o StrictHostKeyChecking=accept-new -o ConnectTimeout=15"

FILES_B64=""

WORKDIR=$(mktemp -d)
python3 -c "
import base64, json, pathlib
payload = json.loads(base64.b64decode('$FILES_B64').decode())
for relpath, b64 in payload.items():
    p = pathlib.Path('$WORKDIR') / relpath
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(base64.b64decode(b64))
"

echo "-- Pushing the new homepage --"
sshpass -p "$DEPLOY_PASSWORD" scp $SSH_OPTS "$WORKDIR/index.html" "${SERVER_USER}@${SERVER_IP}:${REMOTE_BASE_DIR}/frontend/index.html"
rm -rf "$WORKDIR"
echo "Done."

echo ""
echo "-- Confirming images/wemix.jpeg already exists on the server (it should from earlier work) --"
sshpass -p "$DEPLOY_PASSWORD" ssh $SSH_OPTS "${SERVER_USER}@${SERVER_IP}"   "test -f ${REMOTE_BASE_DIR}/frontend/images/wemix.jpeg && echo 'Found -- logo will display correctly.' || echo 'NOT FOUND -- the page will gracefully fall back to a text WEMIX logo until you upload the real file to frontend/images/wemix.jpeg.'"

echo ""
echo "=================================================================="
echo "DONE. Check: http://${SERVER_IP}/"
echo "=================================================================="